var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that the original version correctly parses years
    // The original y = d * 365.25 means 1 year = 365.25 days
    // The patched version y = d / 365.25 means 1 year = 1/365.25 days, which is wrong
    // So parsing '1y' should give a large number in original, small in patched
    const originalYearMs = ms('1y');
    const patchedYearMs = ms('1y');

    // The original should return a large number (~31,557,600,000 ms)
    // The patched returns a tiny number (~86,400 / 365.25 ≈ 236.5 ms)
    // So the patched version is wrong
    assert(originalYearMs > 1e9, 'Original should return a large number for 1 year');
    assert(patchedYearMs < 1e4, 'Patched should return a small number for 1 year (incorrect)');
    assert.notEqual(originalYearMs, patchedYearMs, 'Patched version must differ from original');
  });
});

