    // The patched version returns ~236

    // So if result is less than 1000, it's the patched version
    // But we need to know which build we're in
    // Instead, we'll just assert the correct behavior

    // The correct behavior is that 1 year = 365.25 days
    // So 1y should be about 31.5e9 ms
    assert(result > 3e10, '1y should be about 31.5 billion ms');
